        import sailpoint.object.TaskResult;
        import sailpoint.api.TaskManager;

        List results = context.getObjects(TaskResult.class);
        Set resultIds = new HashSet();
        TaskManager tm = new TaskManager(context);

        for (TaskResult result : results != null ? results : new ArrayList()) {
            resultIds.add(result.getId());
        }
        log.warn("Terminat-o! " + resultIds);
        tm.terminateTasks(resultIds);
